def make_metavar(self) -> str:
    if self.metavar is not None:
        return self.metavar

    metavar = self.type.get_metavar(self)

    if metavar is None:
        metavar = self.type.name.upper()

    if self.nargs != 1:
        metavar += "..."

    return metavar

